<script>
const key='beyond-health-v01',state=JSON.parse(localStorage.getItem(key)||'{"checkins":[],"notes":[]}');let mood='';const $=s=>document.querySelector(s),show=m=>{let t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)},save=()=>localStorage.setItem(key,JSON.stringify(state));$('#todayDate').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active');render()});document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{mood=b.dataset.mood;document.querySelectorAll('[data-mood]').forEach(x=>x.classList.toggle('active',x===b));let p={Grounded:['Keep the rhythm.','A short moment of appreciation can help you carry that steadiness forward.','Name the good','1 minute · reflection'],Tired:['Make the next thing smaller.','Try a brief reset before you ask more from yourself.','Reset your body','2 minutes · movement'],Stretched:['Pause before you push.','Let your breath become one small place to land.','Box breathing','1 minute · reset'],Hopeful:['Build on what feels possible.','Capture one sentence about what you want to make room for today.','Name the good','1 minute · reflection'],Heavy:['Be gentle with the next hour.','You do not have to solve everything at once. Try one quiet breath.','Box breathing','1 minute · reset']}[mood];$('#suggestionTitle').textContent=p[0];$('#suggestionCopy').textContent=p[1];$('#practiceName').textContent=p[2];$('#practiceTime').textContent=p[3]});['energy','stress','sleep'].forEach(id=>$('#'+id).oninput=e=>$('#'+id+'Out').value=e.target.value);$('#saveCheckin').onclick=()=>{if(!mood)return show('Choose a feeling first.');state.checkins.unshift({mood,energy:+$('#energy').value,stress:+$('#stress').value,sleep:+$('#sleep').value,at:new Date().toISOString()});state.checkins=state.checkins.slice(0,60);save();show('Today’s check-in is saved.');render()};$('#journalForm').onsubmit=e=>{e.preventDefault();let text=$('#journalText').value.trim();if(!text)return;state.notes.unshift({text,at:new Date().toISOString()});state.notes=state.notes.slice(0,60);save();$('#journalText').value='';show('Your note is saved.');render()};let begin=n=>show(n+' is ready. Take one unhurried minute.');$('#startPractice').onclick=()=>begin($('#practiceName').textContent);document.querySelectorAll('.practice-start').forEach(b=>b.onclick=()=>begin(b.dataset.practice));function esc(s){let d=document.createElement('div');d.textContent=s;return d.innerHTML}function icon(m){return({Grounded:'☼',Tired:'☾',Stretched:'↯',Hopeful:'✦',Heavy:'♥'})[m]||'◌'}function render(){let f=d=>new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(d));$('#journalList').innerHTML=state.notes.length?state.notes.slice(0,5).map(n=>`<article class="entry"><span class="entry-icon">✎</span><span><strong>${esc(n.text)}</strong><span>Private reflection</span></span><time>${f(n.at)}</time></article>`).join(''):'<p class="empty">Your notes will appear here.</p>';$('#checkinList').innerHTML=state.checkins.length?state.checkins.slice(0,5).map(c=>`<article class="entry"><span class="entry-icon">${icon(c.mood)}</span><span><strong>${c.mood}</strong><span>Energy ${c.energy}/5 · Stress ${c.stress}/5 · Sleep ${c.sleep}/5</span></span><time>${f(c.at)}</time></article>`).join(''):'<p class="empty">No check-ins yet. Begin with Today.</p>';let n=state.checkins.length,avg=n?Math.round(state.checkins.reduce((a,c)=>a+c.energy,0)/n*20):0;$('#insightBar').style.width=avg+'%';if(n){$('#insightHeadline').textContent=`You checked in ${n} time${n===1?'':'s'}.`;$('#insightText').textContent=`Your average energy is ${Math.round(state.checkins.reduce((a,c)=>a+c.energy,0)/n)} out of 5. Keep noticing what helps; this is a reflection, not a diagnosis.`}}render();
</script></body></html>
